create index if not exists intake_customer_idx on public.client_intake_forms(customer_id,created_at desc);
create index if not exists progress_customer_idx on public.consultation_progress(customer_id,created_at desc);
create index if not exists progress_consultation_idx on public.consultation_progress(consultation_id,created_at desc);
create index if not exists visits_customer_idx on public.portal_visits(customer_id,visit_date desc);
create index if not exists consultations_customer_idx on public.portal_consultations(customer_id,starts_at desc);
create index if not exists consultations_start_idx on public.portal_consultations(starts_at,id);
create or replace function public.portal_customer_details(p_id uuid) returns jsonb language sql stable security invoker set search_path=public as $$
select jsonb_build_object('customer',(select to_jsonb(c) from portal_customers c where id=p_id),'intakes',coalesce((select jsonb_agg(x) from (select id,customer_id,created_at,reviewed_at from client_intake_forms where customer_id=p_id order by created_at desc) x),'[]'),'consultations',coalesce((select jsonb_agg(x) from (select id,customer_id,starts_at,status from portal_consultations where customer_id=p_id order by starts_at desc) x),'[]'),'visits',coalesce((select jsonb_agg(v order by visit_date desc) from portal_visits v where customer_id=p_id),'[]'),'progress',coalesce((select jsonb_agg(n order by created_at desc) from consultation_progress n where customer_id=p_id),'[]')) $$;
create or replace function public.portal_consultation_details(p_id uuid) returns jsonb language sql stable security invoker set search_path=public as $$ select jsonb_build_object('consultation',(select to_jsonb(c) from portal_consultations c where id=p_id),'progress',coalesce((select jsonb_agg(n order by created_at desc) from consultation_progress n where consultation_id=p_id),'[]')) $$;
create or replace function public.portal_dashboard_summary() returns jsonb language sql stable security invoker set search_path=public as $$ select jsonb_build_object('customers',(select count(*) from portal_customers),'consultations',(select count(*) from portal_consultations where status='scheduled' and starts_at>=now()),'intakes',(select count(*) from client_intake_forms where reviewed_at is null),'bookings',(select count(*) from consultation_orders where status='needs_attention'),'issues',(select count(*) from integration_events where state='failed'),'notification_count',(select count(*) from notification_jobs where state in ('failed','unknown')),'notifications',coalesce((select jsonb_agg(x) from (select kind,state,created_at,last_error from notification_jobs where state in ('failed','unknown') order by created_at desc limit 5) x),'[]'),'upcoming',coalesce((select jsonb_agg(x) from (select c.id,c.customer_id,c.starts_at,c.status,jsonb_build_object('name',p.name) as portal_customers from portal_consultations c left join portal_customers p on p.id=c.customer_id where c.status='scheduled' and c.starts_at>=now() order by c.starts_at limit 5) x),'[]')) $$;
revoke all on function public.portal_customer_details(uuid),public.portal_consultation_details(uuid),public.portal_dashboard_summary() from public,anon;
grant execute on function public.portal_customer_details(uuid),public.portal_consultation_details(uuid),public.portal_dashboard_summary() to authenticated;
create or replace function public.publish_availability(p_slots jsonb) returns integer language plpgsql security invoker set search_path=public as $$ declare item jsonb; slot_id uuid; n integer:=0; begin
if not public.techniq_is_admin() then raise exception 'Unauthorized'; end if;
for item in select value from jsonb_array_elements(p_slots) loop
 select id into slot_id from portal_availability where starts_at=(item->>'starts_at')::timestamptz for update;
 if exists(select 1 from consultation_orders where availability_id=slot_id and status in ('paid','awaiting_payment','creating_checkout','needs_attention')) then raise exception 'A selected time is booked. Refresh availability.'; end if;
 if slot_id is null then insert into portal_availability(starts_at,ends_at,enabled) values((item->>'starts_at')::timestamptz,(item->>'starts_at')::timestamptz+interval '30 minutes',(item->>'enabled')::boolean); else update portal_availability set enabled=(item->>'enabled')::boolean where id=slot_id; end if;n:=n+1;
end loop;return n;end $$;
revoke all on function public.publish_availability(jsonb) from public,anon;
grant execute on function public.publish_availability(jsonb) to authenticated;
create or replace function public.portal_sales_summary() returns jsonb language sql stable security invoker set search_path=public as $$ select jsonb_build_object('total',coalesce(sum(amount_cents),0),'count',count(*),'current',coalesce(sum(amount_cents) filter(where paid_at>=date_trunc('month',now())),0),'current_count',count(*) filter(where paid_at>=date_trunc('month',now())),'previous',coalesce(sum(amount_cents) filter(where paid_at>=date_trunc('month',now())-interval '1 month' and paid_at<date_trunc('month',now())),0),'previous_count',count(*) filter(where paid_at>=date_trunc('month',now())-interval '1 month' and paid_at<date_trunc('month',now())),'recent',coalesce((select jsonb_agg(x) from(select paid_at,amount_cents from storefront_payments order by paid_at desc limit 10)x),'[]'),'top',coalesce((select jsonb_agg(x) from(select product_name,sum(quantity) as quantity from storefront_order_items i where exists(select 1 from storefront_payments p where p.square_order_id=i.square_order_id) group by product_name order by sum(quantity) desc limit 5)x),'[]')) from storefront_payments $$;
revoke all on function public.portal_sales_summary() from public,anon;
grant execute on function public.portal_sales_summary() to authenticated;
